def solve(g):
    h=len(g); w=len(g[0])
    # find 2-blocks and anchors
    blocks=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]==2 and (r==0 or g[r-1][c]!=2) and (c==0 or g[r][c-1]!=2):
                # start of potential block
                br,bc=r,c
                while br+1<h and g[br+1][bc]==2: br+=1
                while bc+1<w and g[r][bc+1]==2: bc+=1
                if (br-r+1)*(bc-bc+1)>=2 and g[r][bc]!=2 and g[br][c]!=2:
                    blocks.append((r,c,br,bc))
    out=[row[:] for row in g]
    dirs={'UL':(-1,-1),'UR':(-1,1),'DL':(1,-1),'DR':(1,1)}
    for (r0,c0,r1,c1) in blocks:
        anchors={}
