            rr,cc=r0+d*0 if False else 0
            rr,cc=r0+(r1-r0)//2 if False else 0
            dr,dc=dv[0]*(r1-r0+1)/2, dv[1]*(c1-c0+1)/2
            rr=int(round(r0 - dv[0]*max(c1-c0+1, 1)))  # placeholder
        # anchor = diagonal neighbor outward from block center
        cr=(r0+r1)//2; cc=(c0+c1)//2
        for name,(dr_,dc_) in dirs.items():
            ar,ac=cr+dr_, cc+dc_
            anchors[name]=(ar,ac)
        # rotate colors clockwise: UR<-UL, LR<-UR, DL<-LR, UL<-DL
        newc={}
        for n in dirs:
            prev = { 'UR':'UL','LR':'UR','DL':'LR','UL':'DL' }.get(n, n)
            newc[n] = g[anchors[prev][0]][anchors[prev][1]]
        for n,(ar,ac) in list(anchors.items()):
            out[ar][ac]=newc[n]
            dr_,dc_=dirs[n]
            rr,cc=ar,ac
            while True:
                rr+=dr_; cc+=dc_
                if not(0<=rr<h and 0<=cc<w): break
                if out[rr][cc]!=0 and out[rr][cc]!=2: break
                out[rr][cc]=newc[n]
    return out

